  h.js("document.querySelector('#model-name').value='synthetic-draft-deepseek';document.querySelector('#api-key').value='SYNTHETIC-UNSAVED-KEY';document.querySelector('#provider-select').value='glm';document.querySelector('#provider-select').dispatchEvent(new Event('change'));document.querySelector('#model-name').value='synthetic-draft-glm';document.querySelector('#provider-select').value='deepseek';document.querySelector('#provider-select').dispatchEvent(new Event('change'))");jsCheck("document.querySelector('#model-name').value==='synthetic-draft-deepseek'&&document.querySelector('#api-key').value==='SYNTHETIC-UNSAVED-KEY'","Switching providers preserves each unsaved draft");click("#reveal-key");jsCheck("document.querySelector('#api-key').type==='text'&&document.querySelector('#reveal-key').getAttribute('aria-pressed')==='true'","Reveal button affects current input with accessible state");click("#reveal-key");jsCheck("document.querySelector('#api-key').type==='password'","Hide key works without exposing persisted key");h.js("document.querySelector('#api-key').value='';document.querySelector('#model-advanced').open=true;document.querySelector('#api-protocol').scrollIntoView({block:'center'})");jsCheck("(()=>{const a=document.querySelector('#api-protocol').getBoundingClientRect(),b=document.querySelector('#effort').getBoundingClientRect();return b.top>=a.bottom})()","Protocol/effort are stacked full-width, not cramped half columns");h.screenshot("model-advanced-1.6.1.png");
  click(".model-back");jsCheck("document.querySelector('#chat-input')!==null","Return control goes back to originating AI page");click("[data-page=records]");click("[data-action=record-tools]");check(h.waitText("导出备份")&&h.waitText("恢复记录"),"Backup and restore moved to Records, not removed");String key=privateKey("deepseek");h.js("document.querySelector('#daily-goal').value=87;document.querySelector('#goal-form').requestSubmit()");until("document.querySelector('#toast').innerText.includes('学习目标已保存')");check(settings().getInt("dailyLearningGoal")==87&&privateKey("deepseek").equals(key),"Goal edit preserves model key and profile");click("#close-editor");click("#open-settings");h.js("document.querySelector('#api-key').value='SYNTHETIC-MODEL-ONLY';document.querySelector('#api-url').value='https://example.invalid/v1';document.querySelector('#model-name').value='synthetic-final-model';document.querySelector('#settings-form').requestSubmit()");until("document.querySelector('#toast').innerText.includes('模型配置已加密保存')");check(settings().getInt("dailyLearningGoal")==87&&settings().getJSONObject("profiles").getJSONObject("deepseek").getString("model").equals("synthetic-final-model"),"Model save retains prior goal and stores only selected profile");jsCheck("document.querySelector('#api-key').value===''&&document.querySelector('#api-key').type==='password'","Successful save discards secret draft and returns password mode");check(privateKey("deepseek").equals("SYNTHETIC-MODEL-ONLY"),"New synthetic key saved through encrypted native store");
  h.js("document.querySelector('#model-name').value='synthetic-edited-model';document.querySelector('#settings-form').requestSubmit()");until("document.querySelector('#model-name').value==='synthetic-edited-model'&&document.querySelector('#api-key').value===''");Thread.sleep(300);check(privateKey("deepseek").equals("SYNTHETIC-MODEL-ONLY"),"Blank key preserves existing encrypted key");
  h.js("document.querySelector('#api-url').value='http://example.invalid/v1';document.querySelector('#allow-http').checked=false;document.querySelector('#settings-form').requestSubmit()");until("document.querySelector('#toast').innerText.includes('内网 HTTP')");check(settings().getJSONObject("profiles").getJSONObject("deepseek").getString("baseUrl").equals("https://example.invalid/v1"),"Unapproved HTTP edit rejected without changing saved config");
  h.js("document.querySelector('#api-url').value='https://example.invalid/v1';document.querySelector('#model-advanced').open=true;document.querySelector('#clear-key').checked=true;document.querySelector('#settings-form').requestSubmit()");until("document.querySelector('#api-key').required");check(!settings().getJSONObject("profiles").getJSONObject("deepseek").getBoolean("keyConfigured"),"Explicit key deletion removes only selected model key");click("[data-page=tracks]");until("document.querySelector('#track-data-tools')!==null");click("#track-data-tools");check(h.waitText("导出 GPX")&&h.waitText("导出定位诊断"),"Trajectory exports moved to trajectory-specific management dialog");click("#close-editor");click("[data-page=records]");click("[data-action=user-guide]");check(h.waitText("自动 Wiki：默认整理，无需配置"),"Offline manual explains default policy and new entry points");click("#close-editor");
  // Empty only synthetic test queue before isolating automatic processing; do not backfill all history.
  while(queue().getInt("count")>0)h.call("ackWikiQueue",new JSONObject().put("jobs",queue().getJSONArray("jobs")));h.call("saveSettings",new JSONObject().put("settings",new JSONObject().put("profile",profile("deepseek","SYNTHETIC-MODEL-ONLY")).put("dailyLearningGoal",87)));h.call("saveRecord",new JSONObject().put("record",note("model-auto-source","合成自动整理：修改记录后无需再次开启开关。本轮内容版本："+System.currentTimeMillis())).put("allowDuplicate",true));reload();mock();getTargetContext().getSharedPreferences("wiki-automation",0).edit().putInt("used",0).commit();h.js("AutoWiki.kick(10)");for(int i=0;i<200&&queue().getInt("count")>0;i++)Thread.sleep(100);check(queue().getInt("count")==0&&find("model-auto-source").has("wikiTopics"),"New record automatically classified/compiled without opt-in form");jsCheck("__calls.some(p=>p.automaticWiki&&p.tool.name==='compile_learning_wiki')","Automatic processing actually calls compiler, not only displays a status");
  getTargetContext().getSharedPreferences("wiki-automation",0).edit().putInt("used",0).commit();for(int i=0;i<6;i++)WikiAutomation.reserve(getTargetContext());boolean rejected=false;try{WikiAutomation.reserve(getTargetContext());}catch(Exception ex){rejected=true;}check(rejected&&WikiAutomation.settings(getTargetContext()).getInt("dailyUsed")==6,"Native fixed policy allows six requests and blocks seventh");WikiAutomation.configure(getTargetContext(),new JSONObject().put("enabled",false).put("dailyCallLimit",30));check(WikiAutomation.settings(getTargetContext()).getBoolean("enabled")&&WikiAutomation.settings(getTargetContext()).getInt("dailyCallLimit")==6,"Legacy configuration bridge cannot disable or expand fixed policy");
  click("[data-page=chat]");h.screenshot("model-entry-chat-1.6.1.png");click("[data-action=link-options]");check(h.waitText("Exa 匿名 MCP"),"Search options moved to AI assistant");h.js("document.querySelector('#link-settings-form').requestSubmit()");until("!document.querySelector('#editor').open");check(settings().getInt("dailyLearningGoal")==87&&settings().getJSONObject("profiles").getJSONObject("deepseek").getBoolean("keyConfigured"),"Moved search dialog saves/closes without touching model or goal");click("#open-settings");h.js("document.querySelector('#model-name').value='synthetic-unsaved-retap'");click("#open-settings");jsCheck("document.querySelector('#model-name').value==='synthetic-unsaved-retap'","Reopening current model page preserves unsaved input");h.js("document.querySelector('#provider-select').value='glm';document.querySelector('#provider-select').dispatchEvent(new Event('change'))");jsCheck("document.querySelector('.model-status-dot').textContent===''","Provider status changes do not overwrite the decorative dot");
