 void keyboard()throws Exception{mock();click("#open-settings");int height=new JSONArray(h.js("[innerHeight]")).getInt(0);h.js("document.querySelector('#api-key').scrollIntoView({block:'center'})");h.tap("#api-key",false);until("innerHeight<"+(height-100));jsCheck("document.activeElement.id==='api-key'","Real touch opens keyboard for key field");jsCheck("(()=>{const r=document.querySelector('#api-key').getBoundingClientRect(),h=document.querySelector('.app-header').getBoundingClientRect(),n=document.querySelector('.bottom-nav').getBoundingClientRect();return r.top>=h.bottom&&r.bottom<=n.top})()","Key input visible between header and navigation with keyboard open");jsCheck("getComputedStyle(document.querySelector('.model-save')).position==='static'","Save area does not float over the focused input");h.screenshot("model-keyboard-1.6.1.png");sendKeyDownUpSync(android.view.KeyEvent.KEYCODE_BACK);until("innerHeight>="+(height-30));h.js("document.querySelector('#api-key').blur();document.querySelector('#save-model').scrollIntoView({block:'center'})");jsCheck("(()=>{const r=document.querySelector('#save-model').getBoundingClientRect();return r.top>0&&r.bottom<document.querySelector('.bottom-nav').getBoundingClientRect().top})()","Save control reachable after keyboard dismissal");h.screenshot("model-key-section-1.6.1.png");}
 void narrow()throws Exception{mock();click("#open-settings");getTargetContext().getSharedPreferences("wiki-automation",0).edit().putInt("used",6).commit();jsCheck("innerWidth<=360","Narrow-screen test uses real viewport");jsCheck("document.documentElement.scrollWidth<=innerWidth+1","Narrow model page fits width");jsCheck("(()=>{const a=document.querySelector('.brand').getBoundingClientRect(),b=document.querySelector('#open-settings').getBoundingClientRect();return a.right<=b.left&&b.right<=innerWidth})()","Text model entry does not collide with brand on small phone");h.screenshot("model-narrow-1.6.1.png");h.js("document.querySelector('#model-advanced').open=true;document.querySelector('#api-protocol').scrollIntoView({block:'center'})");jsCheck("document.documentElement.scrollWidth<=innerWidth+1","Expanded advanced settings also fit narrow viewport");h.screenshot("model-narrow-advanced-1.6.1.png");}
 @Override public void onStart(){Bundle result=new Bundle();try{cap();h=new MainHost(this);h.open();if(phase.equals("seed"))seedModel();else if(phase.equals("narrow"))narrow();else if(phase.equals("keyboard"))keyboard();else verifyModel();result.putString("stream","PASS "+passed+" model layout/default Wiki/upgrade checks; mock model only\n");finish(Activity.RESULT_OK,result);}catch(Throwable ex){result.putString("stream","FAIL after "+passed+": "+ex+(ex.getCause()==null?"":" / "+ex.getCause())+"\n");finish(Activity.RESULT_CANCELED,result);}}
